@jax.custom_vjp
def magic_clamp(
    x: ArrayLike,
    min_val: Optional[float] = None,
    max_val: Optional[float] = None,
) -&gt; jnp.ndarray:
    x = jnp.clip(x, min_val, max_val)
    return x


def magic_clamp_fwd(
    x: ArrayLike,
    min_val: Optional[float] = None,
    max_val: Optional[float] = None,
) -&gt; Tuple[jnp.ndarray, jnp.ndarray]:
    mask = jnp.zeros_like(x)
    if min_val is not None:
        mask = jnp.where(x &lt; min_val, -1.0, mask)

    if max_val is not None:
        mask = jnp.where(x &gt; max_val, 1.0, mask)
    return magic_clamp(x, min_val, max_val), (mask)


def magic_clamp_bwd(
    mask: ArrayLike,
    grad_output: ArrayLike,
) -&gt; Tuple[jnp.ndarray, None, None]:
    grad_output = jnp.where((mask == 1.0) & (grad_output &lt; 0), 0.0, grad_output)
    grad_output = jnp.where((mask == -1.0) & (grad_output &gt; 0), 0.0, grad_output)
    return grad_output, None, None


magic_clamp.defvjp(magic_clamp_fwd, magic_clamp_bwd)
